export const RATIO_PROPORTION_ACTIVITIES = [
{n:1,type:"mcq",micro:"Rasio sebagai perbandingan kelompok nyata",q:"Sebuah keranjang buah punya 4 apel dan 2 jeruk. Berapa rasio apel terhadap jeruk?",options:["2 banding 4","4 banding 2","6 banding 4"],answer:1,explain:"Rasio apel terhadap jeruk membandingkan 4 apel dengan 2 jeruk, ditulis sebagai 4 banding 2 (atau 4:2).",hint:"Buah mana yang disebutkan LEBIH DULU dalam 'apel terhadap jeruk' — hitungan itu yang pertama dalam rasio."},
{n:2,type:"mcq",micro:"Rasio konkret (mencampur cat)",q:"Resep cat ungu mencampur 3 bagian cat biru dengan 1 bagian cat merah. Jika kamu menggunakan 3 cangkir biru, berapa cangkir merah yang kamu butuhkan?",options:["1 cangkir","4 cangkir","3 cangkir"],answer:0,explain:"Rasio 3:1 berarti untuk setiap 3 bagian biru, kamu butuh tepat 1 bagian merah.",hint:"Rasio 3:1 memberitahumu persis berapa bagian setiap warna yang digunakan bersama."},
{n:3,type:"tf",micro:"Rasio membandingkan dua jumlah",q:"Benar atau Salah: Rasio seperti 5:2 menggambarkan bagaimana dua jumlah dibandingkan satu sama lain, bukan satu jumlah tunggal sendirian.",answer:true,explain:"Rasio selalu membandingkan dua (atau lebih) jumlah satu sama lain, tidak seperti satu angka yang menggambarkan hanya satu jumlah.",hint:"Apakah 5:2 menggambarkan hanya satu kelompok, atau hubungan ANTARA dua kelompok?"},
{n:4,type:"mcq",micro:"Rasio konkret (kelompok kelas)",q:"Sebuah kelas punya 12 anak laki-laki dan 15 anak perempuan. Berapa rasio anak laki-laki terhadap anak perempuan?",options:["15 banding 12","27 banding 12","12 banding 15"],answer:2,explain:"Anak laki-laki terhadap anak perempuan ditulis dalam urutan itu: 12 banding 15.",hint:"Tulis angkanya dalam urutan yang sama seperti yang ditanyakan: laki-laki dulu, lalu perempuan."},
{n:5,type:"mcq",micro:"Rasio konkret (bahan resep)",q:"Sebuah resep panekuk menggunakan 2 cangkir tepung untuk setiap 1 cangkir susu. Jika kamu menggunakan 4 cangkir tepung, berapa banyak susu yang kamu butuhkan untuk mempertahankan rasio yang sama?",options:["1 cangkir","2 cangkir","4 cangkir"],answer:1,explain:"Karena rasionya 2 tepung : 1 susu, menggandakan tepung menjadi 4 cangkir berarti menggandakan susu juga, menjadi 2 cangkir.",hint:"Jika kamu menggandakan satu bagian rasio, kamu harus menggandakan bagian lain juga, untuk menjaganya tetap sama."},
{n:6,type:"mcq",micro:"Rasio konkret (kelereng dalam toples)",q:"Sebuah toples punya 6 kelereng merah dan 4 kelereng biru. Berapa rasio kelereng merah terhadap TOTAL jumlah kelereng?",options:["4 banding 10","6 banding 4","6 banding 10"],answer:2,explain:"Total kelereng = 6+4=10, jadi merah terhadap total adalah 6 banding 10.",hint:"Cari dulu total jumlah kelereng, lalu bandingkan kelereng merah dengan total itu."},
{n:7,type:"tf",micro:"Urutan penting dalam rasio",q:"Benar atau Salah: Rasio 'apel terhadap jeruk' (4:2) TIDAK sama dengan rasio 'jeruk terhadap apel' (2:4) — urutan itu penting.",answer:true,explain:"Urutan rasio itu penting: 4:2 (apel terhadap jeruk) menggambarkan perbandingan yang berbeda dari 2:4 (jeruk terhadap apel), meskipun kedua angka yang sama digunakan.",hint:"Apakah menukar jumlah mana yang disebutkan lebih dulu mengubah apa yang sebenarnya digambarkan rasio itu?"},
{n:8,type:"mcq",micro:"Perbandingan rasio konkret (skor tim)",q:"Tim A mencetak poin dalam rasio 3:2 dibandingkan Tim B di beberapa pertandingan. Jika Tim B mencetak nilai 2 pertandingan lagi dengan laju yang sama, apakah keunggulan Tim A (sebagai rasio) berubah?",options:["Tidak, rasio 3:2 tetap sama selama kedua tim terus mencetak dengan laju yang sama","Ya, rasio berubah menjadi 5:2 karena Tim B yang mencetak lebih banyak otomatis menurunkan nilai Tim A","Ya, rasio berubah menjadi 3:4 karena selisih poin dihitung dari jumlah pertandingan yang berbeda"],answer:0,explain:"Rasio menggambarkan LAJU perbandingan yang konsisten — selama kedua jumlah terus bertumbuh dengan laju relatif yang sama, rasionya sendiri tidak berubah.",hint:"Apakah rasio menggambarkan potret satu-kali, atau hubungan konsisten yang berkelanjutan antara dua jumlah?"},
{n:9,type:"mcq",micro:"Soal cerita konkret (mencampur jus)",q:"Sebuah campuran jus menggunakan 1 bagian konsentrat untuk 3 bagian air. Jika kamu menggunakan 2 cangkir konsentrat, berapa banyak air yang kamu butuhkan?",options:["6 cangkir","3 cangkir","2 cangkir"],answer:0,explain:"Rasio 1:3 berarti setiap 1 bagian konsentrat butuh 3 bagian air; 2 bagian konsentrat butuh 2×3=6 bagian air.",hint:"Kalikan sisi air rasionya dengan jumlah yang sama seperti kamu kalikan sisi konsentratnya."},
{n:10,type:"mcq",micro:"Rasio konkret (penskalaan resep)",q:"Resep kue kering untuk 12 kue kering menggunakan rasio 2:1 tepung terhadap gula (dalam cangkir). Jika kamu ingin membuat kelompok lebih besar menggunakan 6 cangkir tepung, berapa banyak gula yang kamu butuhkan?",options:["2 cangkir","3 cangkir","6 cangkir"],answer:1,explain:"Rasio 2:1 berarti tepung selalu dua kali gula; jika tepung 6 cangkir, gula adalah 6÷2=3 cangkir.",hint:"Dalam rasio 2:1, angka pertama selalu dua kali angka kedua — kerjakan mundur dari jumlah tepung."},
{n:11,type:"mcq",micro:"Identifikasi rasio konkret",q:"Mana dari ini yang secara benar menggambarkan rasio yang membandingkan 8 pensil dengan 5 pena?",options:["13:1","5:8","8:5"],answer:2,explain:"'Pensil terhadap pena' berarti pensil dulu, pena kedua: 8:5.",hint:"Cocokkan urutan kata dalam soal dengan urutan angka dalam rasio."},
{n:12,type:"tf",micro:"Sebuah rasio bisa membandingkan bagian terhadap keseluruhan",q:"Benar atau Salah: Sebuah rasio bisa membandingkan bagian dari sebuah kelompok dengan SELURUH kelompok (seperti 'kelereng merah terhadap semua kelereng'), bukan hanya satu bagian terhadap bagian lain.",answer:true,explain:"Rasio bisa membandingkan bagian-ke-bagian (seperti merah terhadap biru) ATAU bagian-ke-keseluruhan (seperti merah terhadap total), keduanya adalah perbandingan rasio yang valid.",hint:"Bisakah rasio seperti '6 kelereng merah terhadap 10 total kelereng' tetap menjadi rasio yang valid, meskipun satu sisi adalah seluruh kelompok?"},
{n:13,type:"mcq",micro:"Rasio konkret (konteks resep)",q:"Sebuah resep smoothie menggunakan 3 bagian yogurt terhadap 2 bagian buah. Jika kamu menggunakan 9 cangkir yogurt, berapa cangkir buah yang kamu butuhkan?",options:["3 cangkir","6 cangkir","9 cangkir"],answer:1,explain:"9÷3=3, jadi kalikan kedua bagian rasio dengan 3: buah=2×3=6 cangkir.",hint:"Cari tahu angka apa yang kamu kalikan dengan jumlah yogurt, lalu kalikan jumlah buah dengan angka yang sama itu."},
{n:14,type:"mcq",micro:"Rasio konkret (perlengkapan kelas)",q:"Seorang guru membagikan pensil dan penghapus dalam rasio 5:1. Jika 20 pensil dibagikan, berapa penghapus yang dibagikan?",options:["4 penghapus","20 penghapus","5 penghapus"],answer:0,explain:"20÷5=4, jadi 4 penghapus dibagikan (karena rasionya 5 pensil untuk setiap 1 penghapus).",hint:"Berapa kelompok '5 pensil' yang muat dalam 20 pensil? Setiap kelompok mendapat tepat 1 penghapus."},
{n:15,type:"mcq",micro:"Rasio konkret pada peta (skala)",q:"Sebuah mobil model dibangun dengan rasio (skala) 1:20 dibandingkan mobil sebenarnya. Apa arti rasio ini?",options:["Setiap 1 satuan panjang pada mobil sebenarnya mewakili 20 satuan yang sama pada model","Setiap 20 mobil sebenarnya diwakili oleh 1 model yang ditaruh di meja pameran","Setiap 1 satuan panjang pada model mewakili 20 dari satuan yang sama pada mobil sebenarnya"],answer:2,explain:"Rasio skala 1:20 berarti 1 satuan pada model sesuai dengan 20 satuan yang sama pada benda ukuran-penuh yang sebenarnya.",hint:"Dalam model skala, apakah angka yang lebih kecil dalam rasio mewakili model, atau benda sebenarnya?"},
{n:16,type:"mcq",micro:"Perbandingan rasio konkret (dua resep)",q:"Resep A menggunakan rasio 2:1 air terhadap beras. Resep B menggunakan rasio 3:1 air terhadap beras. Resep mana yang menggunakan air relatif LEBIH BANYAK per jumlah beras?",options:["Keduanya menggunakan jumlah yang sama","Resep B","Resep A"],answer:1,explain:"3:1 berarti 3 bagian air per 1 bagian beras, yang lebih banyak air per beras daripada 2:1.",hint:"Bandingkan jumlah air dalam setiap rasio, mengingat jumlah beras (1) sama di keduanya."},
{n:17,type:"tf",micro:"Rasio setara mewakili hubungan yang sama",q:"Benar atau Salah: Rasio 2:3 dan 4:6 mewakili hubungan yang persis sama antara dua jumlah, hanya diskalakan naik.",answer:true,explain:"4:6 hanyalah 2:3 dengan kedua sisi dikalikan 2 — keduanya mewakili hubungan dasar yang sama.",hint:"Jika kamu mengalikan kedua sisi 2:3 dengan angka yang sama, apakah hubungan di antara keduanya berubah?"},
{n:18,type:"mcq",micro:"Rasio konkret (menggandakan resep nyata)",q:"Sebuah resep yang menyajikan 4 orang menggunakan rasio 1:2 mentega terhadap gula (dalam sendok makan). Jika kamu menggandakan seluruh resep untuk menyajikan 8 orang, apakah rasio mentega terhadap gula berubah?",options:["Tidak, rasionya tetap 1:2, meskipun jumlah sebenarnya baik mentega maupun gula digandakan","Ya, rasionya menjadi 2:4 karena kedua angka dalam rasio ikut digandakan menjadi lebih besar","Ya, rasionya menjadi 1:4 karena hanya jumlah gula yang digandakan sedangkan mentega tetap"],answer:0,explain:"Menggandakan KEDUA bahan mempertahankan rasio di antara keduanya persis sama, meskipun jumlah sebenarnya bertambah.",hint:"Jika kedua bagian rasio dikalikan dengan jumlah yang sama, apakah HUBUNGAN di antara keduanya berubah?"},
{n:19,type:"mcq",micro:"Soal cerita konkret (rasio warna)",q:"Sekantong 20 permen memiliki rasio 3:2 permen merah terhadap permen hijau (tanpa warna lain). Berdasarkan rasio ini, apakah lebih banyak permen merah atau hijau?",options:["Persis sama","Lebih banyak permen hijau","Lebih banyak permen merah"],answer:2,explain:"3:2 berarti untuk setiap 3 merah, ada 2 hijau — 3 lebih besar dari 2, jadi ada lebih banyak permen merah.",hint:"Dalam rasio 3:2, angka mana (mewakili warna mana) yang lebih besar?"},
{n:20,type:"mcq",micro:"Memeriksa klaim rasio konkret",q:"Seseorang mengklaim resep dengan '2 cangkir tepung banding 1 cangkir gula' memiliki rasio yang SAMA dengan '3 cangkir tepung banding 1 cangkir gula.' Apakah ini benar?",options:["Ya, rasionya sama karena keduanya menggunakan 1 cangkir gula, dan jumlah tepung hanya perbedaan kecil yang tidak memengaruhi perbandingan sama sekali","Ya, 2:1 dan 3:1 adalah rasio yang sama karena angka terakhir keduanya sama-sama satu, jadi resep kedua tidak berbeda dengan resep pertama","Tidak, 2:1 dan 3:1 adalah rasio yang berbeda — resep kedua menggunakan tepung relatif lebih banyak per gula daripada yang pertama"],answer:2,explain:"2:1 dan 3:1 adalah rasio yang berbeda; 3:1 memiliki tepung relatif lebih banyak per satuan gula daripada 2:1.",hint:"Apakah 2:1 dan 3:1 adalah hubungan yang sama antara tepung dan gula, atau hubungan yang benar-benar berbeda?"},
{n:21,type:"mcq",micro:"Membaca rasio dari sebuah gambar",q:"Sebuah gambar menunjukkan 5 bintang dan 3 lingkaran dikelompokkan bersama. Berapa rasio bintang terhadap lingkaran yang ditunjukkan?",options:["5:3","3:5","8:3"],answer:0,explain:"5 bintang terhadap 3 lingkaran ditulis sebagai 5:3, cocok dengan urutan 'bintang terhadap lingkaran.'",hint:"Hitung setiap bentuk yang ditunjukkan dalam gambar, jaga urutan 'bintang terhadap lingkaran.'"},
{n:22,type:"mcq",micro:"Membaca diagram pita (model batang rasio)",q:"Sebuah diagram pita menunjukkan batang dibagi menjadi 5 bagian sama: 3 bagian berlabel 'jus' dan 2 bagian berlabel 'air.' Rasio jus terhadap air apa yang diwakili ini?",options:["2:3","3:2","5:2"],answer:1,explain:"3 bagian jus terhadap 2 bagian air adalah rasio 3:2.",hint:"Hitung bagian yang diarsir untuk setiap label untuk menemukan rasionya."},
{n:23,type:"mcq",micro:"Membandingkan rasio bergambar",q:"Gambar A menunjukkan 2 titik untuk setiap 1 persegi (rasio 2:1). Gambar B menunjukkan 4 titik untuk setiap 2 persegi (rasio 4:2). Apakah kedua gambar ini menunjukkan rasio dasar yang sama?",options:["Ya, keduanya mewakili hubungan 2:1 yang sama","Tidak, Gambar B memiliki rasio lebih besar","Tidak, Gambar A memiliki rasio lebih besar"],answer:0,explain:"4:2 disederhanakan menjadi 2:1, cocok tepat dengan rasio Gambar A.",hint:"Apakah 4:2 disederhanakan menjadi rasio yang sama dengan 2:1?"},
{n:24,type:"mcq",micro:"Soal cerita diagram pita",q:"Sebuah diagram pita mewakili rasio 3:1 pemain basket terhadap pelatih dalam sebuah tim, dibagi menjadi total 4 bagian sama (3 untuk pemain, 1 untuk pelatih). Jika setiap bagian mewakili 5 orang, berapa banyak pemain yang ada?",options:["5 pemain","20 pemain","15 pemain"],answer:2,explain:"3 bagian × 5 orang per bagian = 15 pemain.",hint:"Kalikan jumlah bagian 'pemain' dengan berapa banyak orang yang diwakili setiap bagian."},
{n:25,type:"order",micro:"Mengurutkan (menskalakan rasio menggunakan gambar)",q:"Urutkan langkah-langkah berikut untuk menggunakan diagram pita menskalakan rasio 2:3 sehingga sisi '2' sama dengan 8.",items:["Kalikan kedua sisi rasio dengan 4, memberikan rasio baru 8:12","Cari tahu angka apa, dikalikan dengan 2, memberikan 8 (yaitu 4)","Identifikasi rasio asli yang perlu diskalakan (2:3)"],answer:[2,1,0],explain:"Pertama identifikasi rasio awal, lalu temukan faktor skala yang dibutuhkan, lalu terapkan faktor itu ke kedua sisi.",hint:"Bisakah kamu menemukan faktor skala yang benar sebelum kamu tahu rasio apa yang kamu mulai?"},
{n:26,type:"mcq",micro:"Model batang rasio (jumlah yang hilang)",q:"Sebuah model batang menunjukkan rasio 4:3 cat merah terhadap cat biru. Jika bagian cat merah mewakili 12 liter, berapa liter yang diwakili satu 'bagian' batang itu?",options:["4 liter","3 liter","12 liter"],answer:1,explain:"12 liter ÷ 4 bagian = 3 liter per bagian.",hint:"Bagi jumlah yang diketahui (12 liter) dengan jumlah bagian yang diwakilinya (4) untuk menemukan nilai satu bagian."},
{n:27,type:"mcq",micro:"Membaca diagram berskala (peta/model)",q:"Sebuah peta menunjukkan skala di mana 1 cm pada peta mewakili 5 km dalam kehidupan nyata (rasio 1:5, dalam cm terhadap km). Jika dua kota berjarak 4 cm pada peta, seberapa jauh jarak sebenarnya?",options:["20 km","4 km","9 km"],answer:0,explain:"4 cm × 5 km per cm = 20 km.",hint:"Kalikan jarak peta dengan berapa km sebenarnya yang diwakili setiap sentimeter peta."},
{n:28,type:"tf",micro:"Diagram pita menunjukkan bagian proporsional",q:"Benar atau Salah: Pada diagram pita yang menunjukkan rasio, semua bagian individual (bagian) digambar sebagai kotak berukuran sama, bahkan jika kelompok berlabel memiliki jumlah bagian yang berbeda.",answer:true,explain:"Setiap bagian individual dalam diagram pita rasio mewakili 'bagian' berukuran sama, meskipun kelompok berlabel berbeda mungkin mencakup JUMLAH bagian sama ini yang berbeda.",hint:"Apakah kotak individual dalam diagram pita semuanya dimaksudkan berukuran sama satu sama lain?"},
{n:29,type:"mcq",micro:"Membaca proporsi bergambar (resep berskala)",q:"Sebuah gambar menunjukkan kartu resep kecil (menyajikan 2) di sebelah kartu resep besar (menyajikan 8), keduanya mencantumkan jumlah bahan. Jika kartu kecil mencantumkan '1 telur,' berapa telur yang harus dicantumkan kartu besar untuk menjaga proporsi yang sama?",options:["2 telur","8 telur","4 telur"],answer:2,explain:"8 porsi ÷ 2 porsi = 4 kali lebih besar, jadi telur juga diskalakan naik 4 kali: 1×4=4 telur.",hint:"Cari berapa kali lebih besar ukuran porsi barunya, lalu kalikan jumlah telur asli dengan faktor yang sama itu."},
{n:30,type:"mcq",micro:"Diagram pita membandingkan dua rasio",q:"Sebuah diagram pita menunjukkan Kelas A dengan rasio 3:2 anak laki-laki terhadap perempuan, dan Kelas B dengan rasio 5:5 anak laki-laki terhadap perempuan. Kelas mana yang memiliki pembagian lebih SETARA antara laki-laki dan perempuan?",options:["Keduanya sama seimbangnya","Kelas B","Kelas A"],answer:1,explain:"5:5 berarti jumlah anak laki-laki dan perempuan yang persis sama, yang lebih seimbang daripada 3:2 (yang lebih condong ke laki-laki).",hint:"Rasio mana yang memiliki dua angka sama, mewakili pembagian yang persis merata?"},
{n:31,type:"mcq",micro:"Membaca diagram berskala (bentuk proporsional)",q:"Sebuah gambar menunjukkan persegi panjang kecil dan persegi panjang besar yang proporsional (bentuk sama, ukuran berbeda) dalam rasio 1:3. Jika persegi panjang kecil lebarnya 2 cm, seberapa lebar persegi panjang besar?",options:["2 cm","6 cm","3 cm"],answer:1,explain:"2 cm × 3 (faktor skalanya) = 6 cm.",hint:"Kalikan lebar persegi panjang kecil dengan faktor skala (3) yang ditunjukkan dalam rasio."},
{n:32,type:"classify",micro:"Setara dengan 2:3, atau tidak?",q:"Kelompokkan setiap rasio bergambar berdasarkan apakah SETARA dengan 2:3, atau TIDAK setara dengan 2:3.",items:["4:6","2:3","6:9","3:2","10:15"],groups:["Setara dengan 2:3","Tidak setara dengan 2:3"],answer:{"Setara dengan 2:3":["4:6","2:3","6:9","10:15"],"Tidak setara dengan 2:3":["3:2"]},explain:"4:6, 6:9, dan 10:15 semuanya adalah 2:3 yang diskalakan naik dengan 2, 3, dan 5. 3:2 adalah urutan terbalik dan merupakan rasio yang berbeda.",hint:"Apakah mengalikan kedua sisi 2:3 dengan angka yang sama pernah memberimu 3:2?"},
{n:33,type:"mcq",micro:"Membaca foto berskala (piktorial)",q:"Sebuah foto dicetak dalam dua ukuran: cetakan kecil dan cetakan besar, mempertahankan proporsi yang sama. Jika cetakan kecil berukuran 4 cm kali 6 cm, dan cetakan besar lebarnya 8 cm, setinggi apa cetakan besar (mempertahankan rasio yang sama)?",options:["8 cm","6 cm","12 cm"],answer:2,explain:"8÷4=2 (faktor skalanya), jadi tinggi juga digandakan: 6×2=12 cm.",hint:"Temukan faktor skala dari lebarnya, lalu terapkan faktor yang sama itu ke tingginya."},
{n:34,type:"mcq",micro:"Soal cerita diagram pita (pencampuran)",q:"Sebuah diagram pita menunjukkan rasio 2:5 konsentrat terhadap air untuk total campuran 7 bagian sama. Jika setiap bagian mewakili 3 liter, berapa liter air dalam campuran itu?",options:["15 liter","21 liter","6 liter"],answer:0,explain:"Air adalah 5 bagian × 3 liter per bagian = 15 liter.",hint:"Kalikan jumlah bagian AIR (5) dengan berapa liter yang diwakili setiap bagian."},
{n:35,type:"mcq",micro:"Membandingkan rasio bergambar (total berbeda)",q:"Gambar Kelompok A menunjukkan 6 bola merah dari total 10 bola. Gambar Kelompok B menunjukkan 9 bola merah dari total 15 bola. Apakah kedua kelompok ini menunjukkan rasio merah-terhadap-total yang sama?",options:["Tidak, Kelompok A memiliki rasio lebih besar","Tidak, Kelompok B memiliki rasio lebih besar","Ya, keduanya disederhanakan menjadi 3:5"],answer:2,explain:"6:10 disederhanakan menjadi 3:5, dan 9:15 juga disederhanakan menjadi 3:5 — keduanya mewakili rasio yang sama.",hint:"Sederhanakan kedua rasio ke bentuk paling sederhana dan bandingkan."},
{n:36,type:"tf",micro:"Estimasi piktorial dengan rasio",q:"Benar atau Salah: Sebuah gambar diagram pita dengan bagian 'biru' yang jauh lebih panjang daripada bagian 'merah' kemungkinan besar mewakili rasio di mana biru adalah angka yang lebih besar, seperti 5:1, bukan sesuatu seperti 1:5.",answer:true,explain:"Bagian yang secara visual jauh lebih panjang mewakili bagian yang secara proporsional lebih besar dari rasio itu.",hint:"Jika bagian biru secara visual jauh lebih panjang dari merah, apakah angka biru dalam rasio itu lebih besar atau lebih kecil?"},
{n:37,type:"mcq",micro:"Membaca diagram arsitektur berskala",q:"Sebuah cetak biru menunjukkan ruangan digambar dengan rasio skala 1:50 (cm di kertas terhadap cm dalam kehidupan nyata). Jika sebuah dinding digambar sepanjang 6 cm pada cetak biru itu, seberapa panjang dinding sebenarnya?",options:["300 cm","6 cm","50 cm"],answer:0,explain:"6 cm × 50 = 300 cm.",hint:"Kalikan panjang yang digambar dengan faktor skala (50) untuk menemukan panjang kehidupan nyatanya."},
{n:38,type:"mcq",micro:"Menjembatani piktorial ke abstrak (pola rasio)",q:"Melihat urutan rasio setara yang ditunjukkan sebagai diagram pita: 1:2, 2:4, 3:6, 4:8, pola apa yang kamu perhatikan?",options:["Setiap rasio dibentuk dengan menjumlahkan 1 pada kedua sisi 1:2 secara berurutan (2:3, 3:4, 4:5)","Setiap rasio dibentuk dengan mengalikan kedua sisi 1:2 dengan bilangan bulat yang sama (1, 2, 3, 4)","Setiap rasio dibentuk dengan mengalikan hanya sisi pertama 1:2 dengan bilangan bulat yang berbeda-beda"],answer:1,explain:"Setiap rasio dalam urutan itu adalah 1:2 dikalikan dengan bilangan bulat yang konsisten (1, 2, 3, lalu 4).",hint:"Bandingkan setiap rasio dalam urutan itu dengan yang paling pertama, 1:2 — angka apa yang dikalikan pada setiap sisi?"},
{n:39,type:"mcq",micro:"Soal cerita piktorial (rasio dari gambar campuran)",q:"Sebuah gambar menunjukkan taman dengan 10 petak sama: 6 petak ditanami bunga dan 4 petak ditanami sayuran. Berapa rasio petak bunga terhadap petak sayuran?",options:["4:6","10:6","6:4 (yang disederhanakan menjadi 3:2)"],answer:2,explain:"6 petak bunga terhadap 4 petak sayuran adalah 6:4, yang disederhanakan menjadi 3:2.",hint:"Bandingkan hitungan petak bunga dengan hitungan petak sayuran, dalam urutan itu."},
{n:40,type:"mcq",micro:"Memilih strategi gambar untuk membandingkan rasio",q:"Untuk membandingkan rasio 3:4 dan 5:8 menggunakan gambar, apa pendekatan yang membantu?",options:["Konversikan kedua rasio agar memiliki angka kedua yang cocok (seperti 3:4=6:8, lalu bandingkan 6:8 dengan 5:8) sehingga bisa dibandingkan langsung","Bandingkan angka pertama saja (3 dan 5) dan abaikan angka kedua, karena angka kedua tidak memengaruhi besarnya rasio sama sekali","Jumlahkan kedua angka di tiap rasio (3+4=7 dan 5+8=13) lalu bandingkan jumlah itu, karena yang lebih besar berarti rasionya lebih besar"],answer:0,explain:"Menskalakan rasio sehingga berbagi angka kedua (atau pertama) yang sama memungkinkan perbandingan visual yang langsung dan adil.",hint:"Akankah menskalakan 3:4 agar juga memiliki '8' sebagai angka keduanya (cocok dengan 5:8) membuat perbandingan lebih mudah?"},
{n:41,type:"mcq",micro:"Menyederhanakan sebuah rasio",q:"Sederhanakan rasio 8:12 ke bentuk paling sederhana.",options:["8:12","2:3","4:6"],answer:1,explain:"Baik 8 maupun 12 bisa dibagi dengan faktor bersama terbesarnya, 4: 8÷4=2 dan 12÷4=3, memberikan 2:3.",hint:"Temukan angka terbesar yang habis membagi baik 8 maupun 12, lalu bagi kedua sisi dengan itu."},
{n:42,type:"mcq",micro:"Menyederhanakan sebuah rasio (angka lebih besar)",q:"Sederhanakan rasio 15:25 ke bentuk paling sederhana.",options:["3:5","15:25","5:3"],answer:0,explain:"Baik 15 maupun 25 habis dibagi 5: 15÷5=3 dan 25÷5=5, memberikan 3:5.",hint:"Temukan faktor bersama terbesar dari 15 dan 25, lalu bagi kedua sisi dengan itu."},
{n:43,type:"mcq",micro:"Menemukan rasio setara",q:"Rasio mana yang setara dengan 3:5?",options:["3:10","9:15","5:3"],answer:1,explain:"3:5 dikalikan 3 pada kedua sisi memberikan 9:15, rasio yang setara.",hint:"Rasio setara berasal dari mengalikan (atau membagi) KEDUA sisi rasio asli dengan angka yang sama."},
{n:44,type:"mcq",micro:"Menemukan nilai yang hilang dalam rasio setara",q:"Jika 4:7 setara dengan 12:x, berapa x?",options:["28","14","21"],answer:2,explain:"4×3=12, jadi kalikan sisi lain dengan 3 juga: 7×3=21.",hint:"Temukan angka apa yang mengalikan 4 untuk mendapat 12, lalu kalikan 7 dengan angka yang sama itu."},
{n:45,type:"mcq",micro:"Menghitung laju satuan",q:"Sebuah mobil menempuh 240 km dalam 4 jam. Berapa laju satuannya (km per 1 jam)?",options:["240 km per jam","60 km per jam","4 km per jam"],answer:1,explain:"240÷4=60, jadi laju satuannya adalah 60 km per jam.",hint:"Bagi total jarak dengan total jumlah jam untuk menemukan laju untuk hanya 1 jam."},
{n:46,type:"mcq",micro:"Menghitung laju satuan (harga)",q:"Sebuah toko menjual 5 apel seharga Rp15.000. Berapa laju satuannya (harga per 1 apel)?",options:["Rp5.000 per apel","Rp15.000 per apel","Rp3.000 per apel"],answer:2,explain:"Rp15.000÷5=Rp3.000 per apel.",hint:"Bagi total harga dengan total jumlah apel untuk menemukan harga hanya 1 apel."},
{n:47,type:"order",micro:"Mengurutkan (menyelesaikan proporsi)",q:"Urutkan langkah-langkah berikut untuk menyelesaikan proporsi 3/5 = x/20.",items:["Bagi kedua sisi dengan 5 untuk menyelesaikan x, memberikan x=12","Kalikan silang: 3×20=5×x, memberikan 60=5x","Susun proporsinya sebagai dua pecahan sama, 3/5 dan x/20"],answer:[2,1,0],explain:"Pertama susun proporsinya, lalu kalikan silang untuk menghilangkan pecahannya, lalu selesaikan persamaan sederhana yang dihasilkan.",hint:"Bisakah kamu mengalikan silang sebelum kamu menyusun proporsinya sebagai dua pecahan sama?"},
{n:48,type:"mcq",micro:"Menyelesaikan proporsi menggunakan perkalian silang",q:"Selesaikan x: 3/5 = x/20.",options:["x=12","x=15","x=8"],answer:0,explain:"Mengalikan silang: 3×20=5×x, jadi 60=5x, dan x=60÷5=12.",hint:"Kalikan silang (pembilang × penyebut lawan di setiap sisi), lalu selesaikan persamaan sederhana yang dihasilkan."},
{n:49,type:"mcq",micro:"Menyelesaikan proporsi (penyusunan soal cerita)",q:"Jika 3 buku tulis biayanya Rp24.000, berapa biaya 7 buku tulis, dengan asumsi laju yang sama?",options:["Rp24.000","Rp56.000","Rp21.000"],answer:1,explain:"Laju satuan: 24.000÷3=8.000 per buku tulis; 7 buku tulis × 8.000 = 56.000.",hint:"Cari dulu harga satuan per buku tulis, lalu kalikan dengan 7."},
{n:50,type:"classify",micro:"Setara dengan 4:6, atau tidak?",q:"Kelompokkan setiap rasio berdasarkan apakah SETARA dengan 4:6, atau TIDAK setara dengan 4:6.",items:["2:3","8:12","4:6","6:4","20:30"],groups:["Setara dengan 4:6","Tidak setara dengan 4:6"],answer:{"Setara dengan 4:6":["2:3","8:12","4:6","20:30"],"Tidak setara dengan 4:6":["6:4"]},explain:"2:3, 8:12, dan 20:30 semuanya setara dengan 4:6 (yang disederhanakan menjadi 2:3). 6:4 adalah urutan terbalik dan merupakan rasio yang berbeda.",hint:"Sederhanakan setiap rasio ke bentuk paling sederhana dan bandingkan dengan 4:6 yang disederhanakan (2:3)."},
{n:51,type:"mcq",micro:"Menskalakan resep menggunakan rasio",q:"Sebuah resep untuk 4 orang menggunakan 300 g beras. Menggunakan rasio yang sama, berapa beras yang dibutuhkan untuk 10 orang?",options:["600 g","300 g","750 g"],answer:2,explain:"Laju satuan: 300÷4=75 g per orang; 10 orang × 75 g = 750 g.",hint:"Cari dulu beras yang dibutuhkan untuk hanya 1 orang, lalu kalikan dengan 10."},
{n:52,type:"mcq",micro:"Menemukan jumlah yang hilang menggunakan proporsi",q:"Sebuah peta memiliki skala 1 cm : 8 km. Jika dua kota berjarak 5 cm pada peta, seberapa jauh jarak sebenarnya?",options:["40 km","5 km","8 km"],answer:0,explain:"5×8=40 km, menerapkan rasio skala pada jarak peta.",hint:"Kalikan jarak peta dengan faktor skala (8 km per cm)."},
{n:53,type:"mcq",micro:"Rasio dan kecepatan",q:"Seorang pelari menempuh 5 km dalam 25 menit dengan kecepatan tetap. Dengan kecepatan yang sama, berapa lama untuk menempuh 8 km?",options:["13 menit","25 menit","40 menit"],answer:2,explain:"Laju satuan: 25÷5=5 menit per km; 8 km × 5 menit = 40 menit.",hint:"Cari waktu yang dibutuhkan untuk berlari hanya 1 km, lalu kalikan dengan 8."},
{n:54,type:"mcq",micro:"Soal cerita (rasio dan jumlah total)",q:"Sebuah campuran menggunakan cat merah dan kuning dalam rasio 2:3, membuat total 25 liter. Berapa liter cat merah yang digunakan?",options:["15 liter","10 liter","25 liter"],answer:1,explain:"2+3=5 total bagian; 25÷5=5 liter per bagian; merah = 2×5=10 liter.",hint:"Jumlahkan kedua angka rasio untuk menemukan total jumlah bagian, lalu bagi total jumlahnya dengan itu."},
{n:55,type:"mcq",micro:"Membandingkan laju (pembelian terbaik)",q:"Toko A menjual 6 pena seharga Rp18.000. Toko B menjual 4 pena seharga Rp10.000. Toko mana yang menawarkan harga per pena yang lebih baik?",options:["Toko B","Toko A","Harga per pena sama"],answer:0,explain:"Toko A: 18.000÷6=3.000 per pena. Toko B: 10.000÷4=2.500 per pena. Toko B lebih murah per pena.",hint:"Hitung harga satuan (per 1 pena) untuk setiap toko, lalu bandingkan."},
{n:56,type:"tf",micro:"Memeriksa perhitungan proporsi dengan estimasi",q:"Benar atau Salah: Jika kamu menyelesaikan proporsi 2/5=x/50 dan menghitung x=200, kemungkinan ada yang salah.",answer:true,explain:"Karena 50 adalah 10 kali 5, x juga harus 10 kali 2, artinya x seharusnya 20, bukan 200 — kemungkinan kesalahan perkalian silang atau pembagian.",hint:"Jika penyebut pecahan kedua (50) 10 kali lebih besar dari yang pertama (5), bukankah pembilangnya juga harus 10 kali lebih besar?"},
{n:57,type:"mcq",micro:"Soal cerita (rasio, penskalaan bahan menurun)",q:"Sebuah resep untuk 8 porsi menggunakan 400 g pasta. Berapa pasta yang dibutuhkan untuk hanya 2 porsi, mempertahankan rasio yang sama?",options:["100 g","400 g","200 g"],answer:0,explain:"Laju satuan: 400÷8=50 g per porsi; 2 porsi × 50 g = 100 g.",hint:"Cari pasta yang dibutuhkan untuk hanya 1 porsi dulu, lalu kalikan dengan 2."},
{n:58,type:"mcq",micro:"Hubungan fakta (rasio dan pecahan)",q:"Karena rasio 1:4 berarti 'untuk setiap 1 bagian, ada 4 bagian,' pecahan apa dari TOTAL yang diwakili bagian '1' itu?",options:["4/5","1/5","1/4"],answer:1,explain:"1:4 berarti 1+4=5 total bagian, jadi bagian '1' mewakili 1/5 dari total.",hint:"Jumlahkan kedua sisi rasio untuk menemukan total jumlah bagian, lalu bandingkan bagian '1' dengan total itu."},
{n:59,type:"mcq",micro:"Membandingkan jumlah berskala",q:"Mana yang jumlahnya lebih besar: 3/4 dari 60, atau bagian rasio 5:7 diterapkan pada total 60 (menemukan bagian '5')?",options:["Bagian rasio 5:7 (yaitu 25)","Keduanya sama","3/4 dari 60 (yaitu 45)"],answer:2,explain:"3/4 dari 60=45. Untuk 5:7 (total 12 bagian) dari 60: 60÷12=5 per bagian, jadi bagian '5' = 25. 45 lebih besar dari 25.",hint:"Hitung kedua nilai secara tepat, lalu bandingkan secara langsung."},
{n:60,type:"mcq",micro:"Memilih pendekatan yang tepat",q:"Sebuah soal mengatakan: 'Sebuah resep menggunakan tepung dan gula dalam rasio 5:2, dan kamu punya tepat 2 cangkir gula. Berapa tepung yang kamu butuhkan?' Apa pendekatan yang benar?",options:["Susun proporsi 5/2 = 2/x dan selesaikan x, karena jumlah gula harus berada di sebelah kanan dalam proporsi itu","Kalikan 5 dengan 2 untuk mendapat 10 cangkir tepung, karena rasio selalu diselesaikan dengan mengalikan kedua angkanya","Susun proporsi 5/2 = x/2 dan selesaikan x, ATAU sadari jumlah gula sudah cocok dengan angka gula dalam rasio, jadi tepung = 5"],answer:2,explain:"Karena jumlah gula (2 cangkir) tepat cocok dengan sisi gula rasionya (2), jumlah tepung langsung sama dengan sisi tepung rasionya (5) — atau kamu bisa menyusun dan menyelesaikan proporsi 5/2=x/2.",hint:"Apakah jumlah gula yang diberikan (2 cangkir) cocok dengan angka yang sudah ada dalam rasio itu sendiri?"},
{n:61,type:"mcq",micro:"Mengapa rasio memungkinkan penskalaan yang adil",q:"Sebuah resep untuk 4 orang perlu diskalakan untuk menyajikan 15 orang. Mengapa memahami rasio dan proporsi sangat penting di sini, alih-alih hanya menebak jumlah baru?",options:["Karena menjaga setiap bahan dalam PROPORSI relatif yang SAMA adalah apa yang mempertahankan rasa dan tekstur resep pada ukuran berapa pun, dan menebak berisiko mengacaukan keseimbangan itu","Karena rasa dan tekstur resep tidak bergantung pada perbandingan bahan, sehingga cukup menggandakan salah satu bahan lalu menebak bahan lainnya sesuai selera pembuat","Karena menambah jumlah bahan dengan angka yang sama pada semua bahan (misalnya +11) sudah mempertahankan proporsi resep secara tepat pada ukuran berapa pun"],answer:0,explain:"Penskalaan proporsional menjamin setiap bahan bertumbuh dengan jumlah relatif yang sama, mempertahankan keseimbangan resep — menebak berisiko hasil yang tidak seimbang.",hint:"Jika kamu menebak jumlah bahan baru alih-alih menskalakan secara proporsional, bisakah keseimbangan (dan rasa) resep itu terganggu?"},
{n:62,type:"open",micro:"Analisis kesalahan",q:"Seorang siswa menyelesaikan proporsi 4/6=x/9 dengan menulis x=4+3=7 (hanya menjumlahkan angka). Temukan kemungkinan kesalahannya dan jelaskan metode yang benar.",explain:"Membingungkan 'jumlahkan angka yang sama' dengan 'kalikan dengan faktor skala yang sama' adalah salah satu kesalahan proporsi yang paling umum.",hint:"Haruskah menyelesaikan proporsi melibatkan menjumlahkan angka yang sama ke kedua sisi, atau mengalikan dengan faktor skala yang sama?",sample:"Siswa itu menebak dengan penjumlahan sederhana alih-alih menggunakan penalaran proporsional — metode yang benar adalah memperhatikan 9 adalah 6×1,5, jadi x juga harus 4×1,5=6 (atau kalikan silang: 4×9=6×x, memberikan 36=6x, jadi x=6), karena proporsi membutuhkan KEDUA sisi diskalakan dengan faktor pengali yang sama, bukan sekadar dijumlahkan."},
{n:63,type:"open",micro:"Estimasi vs penalaran tepat",q:"Kapan perkiraan rasio cepat (seperti membulatkan penskalaan resep) sudah cukup baik, dan kapan kamu membutuhkan jumlah proporsional yang tepat? Berikan satu contoh nyata masing-masing.",explain:"Mengenali kapan presisi proporsional benar-benar penting versus kapan perkiraan yang masuk akal sudah cukup mencerminkan penalaran rasio yang matang.",hint:"Pikirkan situasi di mana penskalaan rasio yang tidak presisi tidak terlalu masalah, dibandingkan dengan situasi di mana itu benar-benar masalah.",sample:"Perkiraan cepat sudah cukup untuk hal seperti dengan santai menggandakan resep sup hanya dengan mata; jumlah proporsional yang tepat penting untuk hal seperti menskalakan eksperimen kimia atau dosis obat, di mana rasio yang tidak presisi bisa mengubah hasilnya secara signifikan atau bahkan tidak aman."},
{n:64,type:"mcq",micro:"Penalaran tentang klaim rasio yang menyesatkan",q:"Sebuah iklan mengklaim 'Formula baru kami memiliki DUA KALI rasio bahan aktif!' tanpa menyatakan apa rasio aslinya. Mengapa klaim ini sulit dievaluasi sepenuhnya?",options:["Karena 'dua kali rasio' berarti dua kali lebih banyak bahan aktif apa pun rasio awalnya, sehingga klaim itu sudah jelas dan jujur bagi para pembeli, dan tidak perlu dibandingkan dengan produk lama","Karena 'dua kali rasio' hanya menjadi bermakna setelah kamu tahu rasio AWALNYA — menggandakan jumlah yang sangat kecil tetap kecil, sementara menggandakan jumlah besar adalah perubahan besar","Karena kata rasio dilarang dipakai dalam iklan, dan setiap klaim bahan aktif harus dinyatakan dalam persen tanpa perbandingan dengan formula lama mana pun yang pernah dijual produsen"],answer:1,explain:"Klaim 'rasio digandakan' tidak bermakna tanpa mengetahui rasio aslinya — menggandakan jumlah awal yang sangat kecil tetap menghasilkan jumlah kecil.",hint:"Apakah mengetahui HANYA bahwa suatu rasio 'digandakan' memberitahumu sesuatu yang bermakna tanpa juga mengetahui apa yang digandakannya?"},
{n:65,type:"open",micro:"Penalaran dunia nyata",q:"Mengapa mencampur cat, semen, atau obat dalam rasio yang SALAH (bahkan jika jumlah totalnya benar) sering menyebabkan masalah nyata?",explain:"Ini mencerminkan pemahaman dunia nyata yang genuine bahwa jumlah total yang benar tidak menjamin hasil yang benar jika rasio internalnya salah.",hint:"Bisakah dua campuran memiliki TOTAL volume yang persis sama tetapi berperilaku sangat berbeda jika rasio internalnya berbeda?",sample:"Rasio antara bahan-bahan (bukan hanya jumlah totalnya) menentukan sifat sebenarnya campuran itu — misalnya, semen dengan terlalu sedikit semen relatif terhadap pasir dan kerikil mungkin tidak mengeras dengan benar, meskipun total volume yang dicampur cocok dengan resepnya, menunjukkan bahwa mendapatkan proporsi RELATIF yang benar sama pentingnya dengan, atau lebih penting dari, jumlah total itu."},
{n:66,type:"mcq",micro:"Memilih strategi yang efisien",q:"Untuk menskalakan rasio 2:5 naik sehingga angka pertamanya 20, strategi mana yang paling cepat?",options:["Sadari bahwa 20 adalah 2+18, jadi tambahkan 18 pada kedua sisi rasio, memberikan 20:23","Kalikan hanya sisi pertama dengan 10 dan biarkan sisi kedua tetap, memberikan 20:5","Sadari bahwa 20 adalah 2×10, jadi kalikan kedua sisi rasio dengan 10, memberikan 20:50"],answer:2,explain:"Mengenali faktor skalanya (10, karena 2×10=20) membiarkanmu cepat menskalakan kedua sisi sekaligus.",hint:"Angka apa, dikalikan dengan 2, memberimu 20? Terapkan angka yang sama itu ke sisi lain."},
{n:67,type:"open",micro:"Menyelidiki perbedaan hasil",q:"Dua orang menskalakan rasio 3:4 naik sehingga angka pertamanya 15, dan mendapat 15:20 dan 15:16. Jelaskan rencana langkah demi langkah untuk menemukan jawaban yang benar.",explain:"Memeriksa apakah kedua sisi diskalakan dengan faktor yang SAMA adalah cara andal memverifikasi atau memperbaiki perbedaan pendapat penskalaan rasio.",hint:"Akankah memeriksa apakah kedua jawaban yang diusulkan menggunakan faktor skala yang SAMA seperti sisi '15' membantumu mengidentifikasi yang benar?",sample:"Temukan faktor skalanya: 15÷3=5, jadi angka kedua juga harus dikalikan 5: 4×5=20, mengonfirmasi 15:20 benar — jawaban lainnya (15:16) kemungkinan berasal dari menjumlahkan angka alih-alih mengalikan, yang bisa diperiksa dengan memverifikasi bahwa 15/3 TIDAK sama dengan 16/4 (15÷3=5, tetapi 16÷4=4, jadi mereka tidak proporsional)."},
{n:68,type:"mcq",micro:"Ketika mental math mungkin gagal",q:"Untuk menskalakan rasio seperti 7:11 naik sehingga angka pertamanya 84, mengapa metode tertulis atau terhitung mungkin lebih aman daripada mental math murni?",options:["Karena 7 dan 11 adalah angka yang sangat mudah, sehingga faktor skala selalu bisa ditemukan di kepala tanpa risiko salah hitung","Karena 7 dan 11 bukan angka 'ramah' sederhana, membuatnya mudah salah menghitung faktor skala murni di kepala","Karena metode tertulis tidak boleh dipakai untuk rasio, dan semua penskalaan rasio harus dilakukan murni di kepala saja"],answer:1,explain:"Rasio yang melibatkan angka kurang 'ramah' (seperti 7 dan 11) lebih rentan kesalahan hitung mental, membuat pendekatan tertulis lebih aman.",hint:"Apakah menskalakan 7:11 semudah dilakukan secara mental seperti menskalakan rasio yang lebih sederhana seperti 2:5?"},
{n:69,type:"open",micro:"Menerapkan penalaran rasio pada keadilan",q:"Tiga mitra bisnis menginvestasikan uang dalam rasio 2:3:5 dan berencana membagi keuntungan dalam rasio yang sama itu. Jika total keuntungannya Rp100.000.000, jelaskan bagaimana rasio menjamin pembagian yang adil berdasarkan investasi awal mereka.",explain:"Menghubungkan pembagian keuntungan berbasis rasio langsung dengan diskusi keadilan nyata yang melibatkan kontribusi tidak sama.",hint:"Akankah membagi keuntungan secara rata (1/3 masing-masing) secara adil mencerminkan fakta bahwa ketiga mitra itu menginvestasikan jumlah yang sangat berbeda awalnya?",sample:"Karena rasionya berjumlah 2+3+5=10 total bagian, setiap bagian bernilai Rp100.000.000÷10=Rp10.000.000, jadi para mitra menerima Rp20.000.000, Rp30.000.000, dan Rp50.000.000 masing-masing — menggunakan rasio yang SAMA seperti investasi awal mereka menjamin pembagian keuntungan secara adil mencerminkan berapa banyak setiap orang awalnya berkontribusi, alih-alih membagi keuntungan secara rata terlepas dari ukuran investasi."},
{n:70,type:"mcq",micro:"Kaitan rasio dan nilai tempat (mengapa urutan penting)",q:"Mengapa menulis rasio dengan urutan yang salah (seperti menulis 'perempuan terhadap laki-laki' sebagai 12:15 padahal seharusnya 15:12) menciptakan masalah nyata?",options:["Karena membalik urutan rasio sebenarnya menggambarkan hubungan yang sama sekali berbeda antara kedua jumlah itu, bukan hanya perbedaan gaya","Karena urutan rasio hanya soal gaya penulisan, dan 12:15 maupun 15:12 selalu menggambarkan hubungan yang sama persis dalam situasi apa pun","Karena urutan rasio hanya penting untuk bilangan kecil, sedangkan untuk bilangan besar urutan boleh dibalik tanpa mengubah arti perbandingannya"],answer:0,explain:"Membalik urutan rasio mengubah hubungan apa yang sebenarnya digambarkannya (12:15 vs 15:12 adalah perbandingan yang berbeda), jadi mendapatkan urutan yang benar penting untuk komunikasi yang akurat.",hint:"Apakah '12 perempuan untuk setiap 15 laki-laki' menggambarkan situasi yang sama dengan '15 perempuan untuk setiap 12 laki-laki'?"},
{n:71,type:"open",micro:"Penalaran estimasi kehidupan nyata",q:"Sebelum memeriksa konversi resep yang tepat, bagaimana cepat memperkirakan 'kira-kira berapa kali lebih besar' kelompok baru itu bisa membantumu merasakan apakah jumlah bahan yang diskalakan naik itu masuk akal?",explain:"Ini adalah penggunaan praktis nyata dari estimasi rasio untuk pemeriksaan kewajaran kehidupan nyata yang cepat pada perhitungan berskala.",hint:"Akankah mengetahui kira-kira berapa kali lebih besar kelompok baru itu membantumu merasakan apakah jumlah bahan berskala tertentu terlihat masuk akal?",sample:"Cepat memperkirakan faktor skalanya (seperti menyadari sebuah resep kira-kira dilipatgandakan tiga kali) membiarkanmu melakukan pemeriksaan mental cepat — jika bahan yang awalnya 2 cangkir tiba-tiba menjadi 20 cangkir setelah 'dilipatgandakan tiga kali,' itu tanda bahaya yang jelas bahwa ada yang salah dalam perhitungan tepatnya, karena melipatgandakan tiga kali seharusnya memberikan kira-kira 6 cangkir, bukan 20."},
{n:72,type:"mcq",micro:"Mengenali pola dalam urutan rasio",q:"1:2, 2:4, 3:6, 4:8 — pola apa yang kamu perhatikan saat urutan rasio ini berlanjut?",options:["Setiap rasio adalah versi bilangan-bulat-berkelipatan sebelumnya dari 1:2, semuanya mewakili hubungan dasar yang sama","Setiap rasio adalah versi sebelumnya ditambah 1 pada kedua sisi, dan pola itu mewakili hubungan yang berbeda-beda setiap kalinya","Setiap rasio menunjukkan hubungan yang berbeda dari 1:2, karena angkanya bertambah sehingga perbandingannya pun ikut berubah"],answer:0,explain:"Setiap rasio dalam urutan ini adalah 1:2 diskalakan dengan bilangan bulat berbeda (1, 2, 3, 4), semuanya mewakili hubungan dasar 1:2 yang sama.",hint:"Apakah semua rasio ini disederhanakan menjadi bentuk paling sederhana yang sama?"},
{n:73,type:"open",micro:"Refleksi pilihan strategi",q:"Jelaskan perhitungan rasio/proporsi nyata di mana kamu akan menggunakan jalan pintas mental math, dan satu di mana kamu ingin menghitung dengan hati-hati dan presisi penuh.",explain:"Mengenali bahwa strategi jalan pintas bekerja paling baik untuk situasi santai dan bertoleransi, sementara konteks kritis-presisi mendapat manfaat dari perhitungan yang hati-hati dan tepat, menunjukkan penilaian strategis yang nyata.",hint:"Apakah jalan pintas rasio bekerja sama baiknya di setiap situasi, atau hanya ketika kesalahan kecil tidak menyebabkan masalah nyata?",sample:"Untuk hal seperti menggandakan resep sederhana (menggunakan jalan pintas mudah menggandakan setiap bahan), jalan pintas mental itu cepat dan andal; tetapi untuk hal seperti menskalakan campuran bahan konstruksi (seperti semen) atau dosis medis berdasarkan berat badan, perhitungan proporsional yang hati-hati dan tepat jauh lebih penting daripada jalan pintas kasar."},
{n:74,type:"mcq",micro:"Menafsirkan rasio perkiraan",q:"Sebuah laporan mengatakan 'rasio taman-terhadap-penduduk kota itu kira-kira 1 taman untuk setiap 5.000 orang.' Apa yang disarankan 'kira-kira' tentang rasio tepatnya?",options:["Rasio sebenarnya persis 1 taman untuk 5.000 orang di setiap bagian kota, tanpa perbedaan sedikit pun antara satu wilayah dan wilayah lain","Rasio sebenarnya jauh lebih kecil dari ini karena laporan biasanya melebih-lebihkan jumlah taman yang tersedia bagi penduduk kota itu","Rasio sebenarnya kemungkinan dekat dengan angka ini tetapi mungkin bukan nilai yang tepat itu secara sempurna di mana pun di kota itu"],answer:2,explain:"'Kira-kira' menandakan perkiraan — rasio seluruh kota yang sebenarnya diharapkan dekat dengan, tetapi belum tentu sempurna dan tepat (atau terdistribusi merata sebagai) 1:5.000.",hint:"Apakah 'kira-kira 1 taman per 5.000 orang' menjanjikan presisi sempurna dan distribusi merata di mana-mana, atau hanya kedekatan keseluruhan yang masuk akal?"},
{n:75,type:"open",micro:"Perhitungan rasio di bawah tekanan",q:"Saat kompetisi memasak yang cepat di mana seorang koki harus cepat menskalakan resep naik atau turun di bawah tekanan waktu, kebiasaan apa yang membantu menghindari kesalahan rasio yang ceroboh bahkan saat terburu-buru?",explain:"Kebiasaan spesifik dan cepat 'temukan satu faktor skala dan terapkan di mana-mana' membantu menjaga akurasi bahkan saat bekerja di bawah tekanan waktu.",hint:"Akankah mengidentifikasi SATU faktor skala yang konsisten dan menerapkannya ke setiap bahan membantu menghindari kesalahan terburu-buru yang tidak konsisten?",sample:"Cepat mengidentifikasi satu faktor skala yang dibutuhkan (seperti 'aku perlu melipatgandakan tiga kali semuanya') dan menerapkan SATU faktor itu secara konsisten ke setiap bahan, alih-alih menghitung ulang setiap bahan secara terpisah dari awal, membantu menghindari kesalahan terburu-buru umum yaitu menskalakan sebagian bahan dengan benar tetapi lupa atau salah menghitung yang lain."},
{n:76,type:"mcq",micro:"Rasio dan laju sebagai gagasan yang berhubungan",q:"Karena 'laju satuan' (seperti km per jam) berasal dari menyederhanakan rasio agar memiliki '1' di satu sisi, bagaimana rasio dan laju berhubungan?",options:["Laju adalah jenis rasio khusus yang sudah diubah sehingga kedua sisinya sama besar, misalnya 1:1 untuk setiap kecepatan","Laju adalah jenis rasio khusus, khususnya yang telah disederhanakan sehingga satu sisi sama dengan tepat 1","Laju bukan rasio sama sekali, karena rasio hanya dipakai untuk perbandingan benda dan tidak untuk jarak atau waktu"],answer:1,explain:"Laju satuan hanyalah rasio yang disederhanakan sehingga satu sisi (biasanya penyebutnya, seperti 'per 1 jam') sama dengan tepat 1.",hint:"Ketika kamu menyederhanakan rasio seperti 240:4 menjadi 60:1, apa yang kamu sebut jenis rasio yang disederhanakan khusus itu?"},
{n:77,type:"open",micro:"Menjelaskan rasio ke orang lain",q:"Seorang siswa yang lebih muda berpikir rasio resep '2 cangkir tepung banding 1 cangkir gula' berarti kamu selalu butuh TEPAT 2 cangkir tepung dan 1 cangkir gula, tidak peduli seberapa besar resepnya. Apa yang akan kamu ajarkan padanya, dan mengapa itu membantu?",explain:"Mengajarkan bahwa rasio menggambarkan HUBUNGAN yang bisa diskalakan, bukan jumlah tetap, mencerminkan pemahaman nyata tentang apa yang sebenarnya diwakili rasio.",hint:"Apakah rasio seperti 2:1 menggambarkan satu jumlah tetap tunggal, atau hubungan yang bisa diskalakan naik atau turun sambil tetap menjadi rasio yang sama?",sample:"Saya akan menjelaskan bahwa rasio 2:1 menggambarkan HUBUNGAN antara tepung dan gula (tepung selalu dua kali gula), bukan jumlah tetap dan tidak berubah — jadi resep yang lebih besar bisa menggunakan 4 cangkir tepung banding 2 cangkir gula, atau 10 cangkir tepung banding 5 cangkir gula, dan itu tetap rasio 2:1 yang sama, memperbaiki kesalahan berpikir bahwa rasio mengunci satu jumlah tetap tertentu selamanya."},
{n:78,type:"mcq",micro:"Mengenali hasil yang tidak mungkin",q:"Kamu diberitahu bahwa menskalakan rasio 3:5 naik (mengalikan kedua sisi dengan bilangan bulat yang sama) menghasilkan rasio baru 9:10. Apa yang harus kamu curigai?",options:["Kesalahan terjadi, karena menskalakan KEDUA sisi rasio dengan angka yang sama harus mempertahankan hubungan yang sama, dan 9:10 tidak disederhanakan kembali menjadi 3:5","Tidak ada kesalahan, karena 9:10 adalah hasil yang wajar bila kedua sisi 3:5 dikalikan dengan bilangan bulat berbeda-beda pada masing-masing sisinya","Tidak ada kesalahan, karena menskalakan rasio 3:5 naik boleh menghasilkan 9:10 asalkan jumlah kedua sisinya tetap sama besar setelah dikalikan"],answer:0,explain:"Menskalakan rasio dengan benar dengan mengalikan kedua sisi dengan angka yang sama selalu mempertahankan hubungan dasarnya — 9:10 tidak disederhanakan menjadi 3:5, menandakan kesalahan (penskalaan 3:5 yang benar dengan 3 akan memberikan 9:15).",hint:"Apakah 9:10 disederhanakan menjadi rasio yang sama dengan 3:5?"},
{n:79,type:"open",micro:"Merancang sistem berbasis rasio yang adil",q:"Rancang cara sederhana bagi toko roti kecil untuk andal menskalakan resepnya naik atau turun untuk berbagai ukuran pesanan, tanpa secara tidak sengaja mengacaukan rasa atau teksturnya.",explain:"Sistem penskalaan berbasis rasio yang jelas dan konsisten dengan daftar periksa verifikasi adalah pendekatan yang benar-benar praktis untuk penskalaan resep yang andal.",hint:"Akankah memiliki satu 'faktor skala' yang jelas diterapkan secara konsisten ke setiap bahan (dengan daftar periksa untuk verifikasi) membantu mencegah satu bahan secara tidak sengaja tertinggal tidak diskalakan?",sample:"Buat kartu resep utama yang mencantumkan setiap bahan sebagai RASIO relatif terhadap satu bahan 'dasar' (seperti tepung), sehingga untuk ukuran pesanan apa pun, tukang roti cukup menghitung jumlah tepung yang dibutuhkan dulu, lalu mengalikan setiap bahan lain dengan faktor skala yang sama itu — menggunakan daftar periksa untuk mengonfirmasi setiap bahan tunggal diskalakan secara konsisten sebelum memulai, untuk menghindari secara tidak sengaja meninggalkan satu bahan pada jumlah aslinya."},
{n:80,type:"mcq",micro:"Pemeriksaan keyakinan rasio",q:"Kamu menghitung nilai yang hilang dalam proporsi 4/9=x/45 tiga kali terpisah dan mendapat 20, 20, dan 11. Apa kesimpulan yang paling masuk akal?",options:["Nilai sebenarnya 11, karena itu angka terkecil dari ketiga percobaan dan paling aman dipakai dalam proporsi, berapa pun faktor skalanya","Nilai sebenarnya sangat mungkin 20, karena cocok dengan dua dari tiga percobaan (dan cocok dengan faktor skala yang benar yaitu 5, karena 45÷9=5 dan 4×5=20)","Ketiga percobaan tidak bisa dipercaya, sehingga proporsi 4/9=x/45 harus diselesaikan dengan cara berbeda dari awal, misalnya dengan menebak"],answer:1,explain:"Ketika sebagian besar percobaan berulang cocok (dua dari tiga mendapat 20), dan nilai itu cocok dengan perhitungan faktor skala yang benar, itu adalah hasil yang bisa dipercaya.",hint:"Jawaban mana yang muncul lebih sering di antara ketiga percobaanmu, dan apakah cocok dengan faktor skala yang benar (45÷9=5)?"},
{n:81,type:"open",micro:"Masalah nyata multi-langkah",q:"Sebuah resep punch buah menggunakan jus dan soda dalam rasio 3:2. Kamu ingin membuat total 20 liter. Berapa liter jus dan berapa liter soda yang kamu butuhkan, dan bagaimana kamu menemukannya?",explain:"Penerapan langsung pembagian rasio multi-langkah pada skenario pencampuran resep nyata.",hint:"Jumlahkan angka rasio untuk menemukan total bagian, bagi total liter dengan itu, lalu kalikan setiap sisi rasio dengan hasilnya.",sample:"Total bagian: 3+2=5; setiap bagian = 20÷5=4 liter; jus = 3×4=12 liter, soda = 2×4=8 liter (periksa: 12+8=20, cocok dengan totalnya) — ditemukan dengan pertama mencari total jumlah bagian rasio, lalu nilai satu bagian, lalu mengalikan setiap sisi rasio dengan nilai itu."},
{n:82,type:"open",micro:"Merancang pemeriksaan anggaran berbasis rasio nyata",q:"Sebuah keluarga berencana membagi anggaran belanja bahan makanan Rp1.500.000 antara 'makanan segar' dan 'barang dapur' dalam rasio 7:3. Berapa yang masuk ke setiap kategori, dan bagaimana kamu menghitungnya?",explain:"Menerapkan pembagian anggaran berbasis rasio nyata langsung pada keputusan keuangan rumah tangga yang sungguhan.",hint:"Cari total jumlah bagian rasio, nilai satu bagian, lalu kalikan setiap sisi rasio dengan nilai itu — dan periksa kedua hasilmu berjumlah kembali ke totalnya.",sample:"Total bagian: 7+3=10; setiap bagian = 1.500.000÷10=150.000; makanan segar = 7×150.000=1.050.000, barang dapur = 3×150.000=450.000 (periksa: 1.050.000+450.000=1.500.000, cocok dengan total anggarannya)."},
{n:83,type:"open",micro:"Menyelidiki klaim rasio yang tidak konsisten",q:"Sebuah perusahaan mengklaim camilan trail mix-nya memiliki 'kacang terhadap buah kering dalam rasio 2:1,' tetapi ketika kamu menimbang sampel sekantong, kamu mengukur 180 g kacang dan 60 g buah kering. Apakah ini cocok dengan rasio yang diklaim?",explain:"Mengenali dan dengan jujur menyelidiki perbedaan rasio nyata, alih-alih mengasumsikan salah satu angka otomatis salah, mencerminkan penalaran matang tentang klaim rasio dalam produk nyata.",hint:"Apakah rasio yang diukur (180:60, disederhanakan) sebenarnya cocok dengan rasio 2:1 yang diklaim?",sample:"Sederhanakan rasio yang diukur: 180:60 dibagi 60 memberikan 3:1, yang TIDAK cocok dengan rasio 2:1 yang diklaim — perbedaan ini patut diselidiki lebih lanjut (memeriksa beberapa kantong, atau melihat informasi nutrisi resmi) alih-alih mengasumsikan labelnya atau pengukuran tunggalmu otomatis benar, karena satu kantong sampel mungkin tidak sepenuhnya mewakili setiap kantong."},
{n:84,type:"open",micro:"Koneksi sejarah/budaya",q:"Cari tahu (atau ingat kembali) bagaimana rasio dan proporsi secara historis digunakan dalam bidang seperti seni, arsitektur, atau navigasi (seperti 'rasio emas' atau skala peta). Jelaskan singkat apa yang kamu temukan.",explain:"Menghubungkan rasio dan proporsi dengan penggunaan sejarah dan lintas-disiplin yang nyata menunjukkan relevansi skill ini yang lebih luas di dunia nyata.",hint:"Mengapa rasio yang konsisten dan dipahami dengan baik (seperti skala peta) mungkin sangat penting secara historis untuk navigasi jarak jauh?",sample:"Rasio dan proporsi telah lama digunakan dalam seni dan arsitektur untuk menciptakan desain yang menyenangkan secara visual dan seimbang (seperti 'rasio emas' yang secara historis dibahas dalam beberapa bangunan dan karya seni klasik), dan dalam navigasi serta pembuatan peta, rasio skala penting untuk secara akurat mewakili jarak dunia nyata yang sangat besar pada peta kecil yang bisa digunakan — menunjukkan bahwa penalaran rasio memiliki kepentingan praktis dan estetika di berbagai bidang, bukan hanya kelas matematika modern."},
{n:85,type:"open",micro:"Masalah pengukuran nyata multi-langkah",q:"Sebuah tangga perlu bersandar pada rasio aman 1:4 (jarak horizontal dari dinding, terhadap tinggi tangga naik dinding). Jika tangga itu perlu mencapai 12 meter naik dinding, seberapa jauh dari dinding dasarnya harus ditempatkan?",explain:"Menerapkan penalaran proporsional berbasis rasio pada skenario pengukuran yang kritis-keselamatan nyata.",hint:"Temukan faktor skala menggunakan tinggi yang diketahui (12), lalu terapkan faktor yang sama itu ke sisi jarak-horizontal rasionya.",sample:"Rasio 1:4 berarti untuk setiap 1 satuan jarak horizontal, ada 4 satuan tinggi; karena tinggi=12, dan 12÷4=3, jarak horizontal harus 1×3=3 meter dari dinding — ditemukan dengan mencari tahu faktor skalanya dari tinggi yang diketahui, lalu menerapkan faktor yang sama itu ke sisi horizontal rasionya."},
{n:86,type:"open",micro:"Refleksi kesalahan rasio",q:"Ceritakan saat nyata (dalam skill ini atau dalam kehidupan nyata) ketika kamu membuat kesalahan dengan rasio atau proporsi — seperti hanya menskalakan satu bagian rasio, membingungkan urutan, atau kesalahan perkalian silang. Apa penyebabnya, dan apa yang akan kamu lakukan berbeda sekarang?",explain:"Merenungkan kesalahan rasio/proporsi pribadi yang nyata, dengan perbaikan konkret, menunjukkan skill ini sudah benar-benar tertanam.",hint:"Ingat kembali momen ketika sebuah perhitungan rasio atau proporsi ternyata salah — apa tepatnya yang salah dalam langkahmu?",sample:"Bersifat personal dan terbuka — tujuannya adalah mengenali penyebab nyata (seperti hanya menskalakan satu sisi rasio alih-alih keduanya, membalik urutan rasio, atau membuat kesalahan hitung saat perkalian silang) dan menyebutkan perbaikan konkret, seperti selalu memeriksa ulang bahwa kedua sisi diskalakan dengan faktor yang sama, atau memverifikasi dengan pemeriksaan yang disederhanakan."},
{n:87,type:"open",micro:"Merancang proyek rasio kelas",q:"Rancang proyek kelas sederhana bagi 30 siswa untuk mempraktikkan rasio dan proporsi nyata — seperti mengukur benda nyata dan menghitung serta membandingkan proporsinya (seperti rasio tinggi-terhadap-rentang-lengan).",explain:"Ini adalah sistem praktis dan langsung untuk andal mempraktikkan perhitungan dan perbandingan rasio nyata menggunakan data pribadi yang genuine.",hint:"Akankah membuat siswa mengukur proporsi tubuh nyata mereka sendiri, lalu menghitung dan membandingkan rasio, membuat latihan itu lebih bermakna daripada soal lembar kerja abstrak saja?",sample:"Minta setiap siswa mengukur tinggi dan rentang lengan mereka sendiri dalam sentimeter, hitung rasio tinggi-terhadap-rentang-lengan pribadi mereka (disederhanakan), lalu bandingkan rasio di seluruh kelas untuk melihat seberapa dekat sebagian besar siswa dengan rasio kira-kira 1:1 — membahas variasi menarik apa pun dan faktor dunia nyata apa yang mungkin menjelaskannya."},
{n:88,type:"open",micro:"Memperkirakan dan memverifikasi jumlah berskala",q:"Perkirakan berapa banyak gula yang kamu butuhkan untuk menskalakan resep yang biasanya menggunakan 150 g gula untuk 6 porsi, naik ke 14 porsi, lalu jelaskan bagaimana kamu akan memverifikasi perkiraanmu.",explain:"Ini menerapkan teknik 'perkirakan menggunakan kelipatan kasar, lalu verifikasi dengan laju satuan tepat' pada skenario penskalaan resep yang nyata.",hint:"Bisakah kira-kira menggandakan jumlah gula memberikan perkiraan yang masuk akal, sebelum menghitung laju satuan tepatnya untuk verifikasi?",sample:"Perkiraan cepat: 14 porsi sedikit lebih dari dua kali 6 porsi, jadi perkiraan kasar mungkin sedikit lebih dari 300 g; kamu bisa memverifikasi ini secara tepat dengan menemukan laju satuannya (150÷6=25 g per porsi) dan mengalikannya dengan 14 (25×14=350 g), mengonfirmasi perkiraannya cukup dekat."},
{n:89,type:"open",micro:"Menyelidiki perbedaan nyata (klaim skala yang bersaing)",q:"Dua peta berbeda dari kota yang sama menunjukkan rasio skala berbeda: 1:10.000 pada satu peta dan 1:25.000 pada peta lainnya. Berikan dua kemungkinan penjelasan berbeda untuk ini, dan bagaimana kamu akan menyelidiki masing-masing.",explain:"Mempertimbangkan beberapa penyebab yang mungkin untuk perbedaan rasio skala dunia nyata, dan cara mengujinya, mencerminkan penalaran investigatif yang genuine.",hint:"Bisakah dua peta dari 'kota yang sama' benar-benar menggunakan skala berbeda karena dirancang untuk tujuan berbeda atau mencakup area berbeda, bukan karena salah satu sekadar salah?",sample:"Kemungkinan 1: kedua peta mungkin sekadar dirancang untuk tujuan berbeda (satu untuk navigasi jalan kaki yang detail, satu untuk gambaran keseluruhan kota yang lebih luas), yang secara alami menggunakan skala berbeda — periksa penggunaan atau judul yang dimaksudkan setiap peta. Kemungkinan 2: satu peta mungkin benar-benar mencakup area geografis yang lebih besar dari yang lain, membutuhkan skala berbeda agar muat pada kertas ukuran sama — bandingkan batas geografis sebenarnya yang ditunjukkan setiap peta."},
{n:90,type:"open",micro:"Kaitan rasio dan statistik",q:"Sebuah sekolah melaporkan rasio siswa-terhadap-guru 18:1. Mengapa satu rasio ini mungkin tidak menceritakan keseluruhan cerita tentang ukuran kelas sebenarnya di seluruh sekolah?",explain:"Ini menghubungkan pemahaman rasio langsung dengan menafsirkan statistik institusional nyata dan batasannya dengan benar.",hint:"Apakah mengetahui HANYA rasio rata-rata seluruh sekolah memberitahumu apakah setiap ruang kelas individual benar-benar memiliki rasio yang persis sama itu?",sample:"Rasio rata-rata seluruh sekolah seperti 18:1 bisa dihitung dari distribusi ukuran kelas nyata yang sangat berbeda — beberapa kelas mungkin hanya punya 10 siswa sementara yang lain punya 26, dan rasionya hanya mencerminkan rata-rata KESELURUHAN di seluruh sekolah, bukan pengalaman sebenarnya setiap ruang kelas individual, menunjukkan mengapa satu rasio ringkasan tidak otomatis mengungkapkan variasi nyata antar ruang kelas."},
{n:91,type:"open",micro:"Mini proyek",q:"Rancang dan hitung skenario berbasis rasio/proporsi nyata (seperti menskalakan resep, mencampur larutan, atau membandingkan harga menggunakan laju satuan), menunjukkan pekerjaanmu dengan jelas. Laporkan hasil dan metodemu.",explain:"Ini adalah penerapan kapstone langsung dari keterampilan rasio dan proporsi pada tugas nyata yang kamu rancang sendiri.",hint:"Akankah menunjukkan setiap langkah perhitungan rasio dengan jelas (bukan hanya jawaban akhir) membuat pekerjaanmu lebih mudah diperiksa dan dipercaya orang lain?",sample:"Bersifat personal dan terbuka — tujuannya adalah mempraktikkan operasi rasio/proporsi nyata (menyederhanakan, menskalakan, menemukan laju satuan, atau menyelesaikan proporsi) dalam skenario realistis yang kamu rancang sendiri."},
{n:92,type:"open",micro:"Menjelaskan rasio ke anak yang jauh lebih muda",q:"Bagaimana kamu akan menjelaskan arti rasio seperti 2:1 kepada anak yang belum pernah melihatnya, menggunakan sesuatu yang mereka pahami?",explain:"Menyederhanakan konsep matematika abstrak menggunakan contoh yang konkret dan relevan menunjukkan pemahaman yang mendalam dan bisa dipindahkan.",hint:"Kegiatan sehari-hari apa yang melibatkan dua item berbeda-warna atau berbeda-jenis (seperti balok mainan) yang akan membantu menjelaskan hubungan 2:1 yang tetap?",sample:"Saya akan menggunakan balok mainan nyata — 'jika kamu selalu membangun dengan 2 balok merah untuk setiap 1 balok biru, itu rasio 2:1 — tidak peduli seberapa besar menaramu jadinya, kamu selalu menggunakan dua kali lebih banyak balok merah daripada biru, dan hubungan tetap antara kedua warna itu persis apa yang digambarkan rasio.'"},
{n:93,type:"open",micro:"Refleksi",q:"Menurutmu mengapa memulai dengan kelompok fisik nyata (seperti keranjang buah atau kelereng campuran) begitu penting sebelum melanjutkan ke penyederhanaan rasio abstrak dan menyelesaikan proporsi?",explain:"Ini mencerminkan wawasan nyata tentang mengapa perjalanan Konkret-Piktorial-Abstrak sangat penting khususnya untuk rasio dan proporsi, skill yang membangun langsung di atas pekerjaan pecahan, desimal, dan persen sebelumnya.",hint:"Akankah aturan penyederhanaan rasio abstrak lebih masuk akal bagi seseorang yang belum pernah menemui situasi rasio fisik nyata, atau bagi seseorang yang sudah pernah?",sample:"Tanpa dulu merasakan apa yang sebenarnya diwakili rasio dalam konteks nyata dan konkret (seperti benar-benar menghitung 4 apel dan 2 jeruk), aturan abstrak (seperti 'bagi kedua sisi dengan faktor bersama terbesar') bisa terasa seperti langkah sembarang untuk dihafal alih-alih sesuatu yang menggambarkan hubungan nyata dan bermakna antara dua jumlah — membangun dari konteks rasio konkret dan nyata dulu membantu aturan dan perhitungan abstrak benar-benar masuk akal nanti."},
{n:94,type:"open",micro:"Keputusan bisnis menggunakan rasio",q:"Sebuah toko roti kecil menemukan bahwa roti terlarisnya menggunakan rasio tepung-terhadap-air 5:3, tetapi perubahan harga pemasok membuat resep yang lebih banyak air lebih murah diproduksi. Keputusan bisnis apa yang mungkin didukung informasi berbasis rasio ini, dan apa yang masih perlu diwaspadai toko roti itu?",explain:"Menerapkan penalaran berbasis rasio pada keputusan trade-off biaya-dan-kualitas bisnis nyata, sambil menandai risiko mengubah rasio yang terbukti tanpa pengujian yang hati-hati.",hint:"Bisakah mengubah rasio tepung-terhadap-air resep roti, bahkan sedikit, berisiko secara nyata mengubah kualitas atau tekstur akhirnya?",sample:"Mereka mungkin mempertimbangkan dengan hati-hati menguji apakah rasio yang sedikit berbeda (dengan sedikit lebih banyak air) bisa mengurangi biaya sambil tetap memenuhi ekspektasi rasa pelanggan — tetapi tetap harus waspada bahwa mengubah rasio yang sudah teruji dengan baik, bahkan sedikit, bisa secara nyata mempengaruhi tekstur dan kualitas akhir roti itu, jadi perubahan apa pun harus diuji dengan hati-hati sebelum diterapkan ke produksi penuh."},
{n:95,type:"open",micro:"Rasio bertemu keadilan (membagi tugas tidak sama)",q:"Dua teman bekerja bersama pada proyek kelompok: satu menghabiskan 6 jam dan yang lain menghabiskan 4 jam. Jika mereka mendapat total Rp250.000 untuk proyek itu, jelaskan bagaimana rasio membantu membagi pembayaran secara adil berdasarkan jam kerja.",explain:"Menghubungkan pembagian pembayaran berbasis rasio langsung dengan diskusi keadilan nyata yang melibatkan kontribusi waktu tidak sama.",hint:"Akankah membagi pembayaran secara rata (setengah masing-masing) secara adil mencerminkan fakta bahwa kedua teman bekerja dengan jumlah jam yang sangat berbeda?",sample:"Jam kerja membentuk rasio 6:4, yang disederhanakan menjadi 3:2 (total 5 bagian); setiap bagian = 250.000÷5=50.000, jadi teman yang bekerja 6 jam mendapat 3×50.000=150.000, dan teman yang bekerja 4 jam mendapat 2×50.000=100.000 — menggunakan RASIO jam kerja (alih-alih pembagian rata 50/50) lebih adil mencerminkan kontribusi waktu sebenarnya setiap orang."},
{n:96,type:"open",micro:"Batasan statistik rasio",q:"Sebuah laporan menyatakan 'rumah sakit ini memiliki rasio perawat-terhadap-pasien 1:4.' Apa yang bisa diberitahukan rasio ini, dan apa yang tidak bisa diberitahukannya sendiri?",explain:"Mengenali bahwa statistik rasio memberikan angka ringkasan yang berguna, tetapi tidak otomatis gambaran penuh bagaimana kondisi bervariasi dalam praktiknya, adalah koneksi berpikir kritis yang penting.",hint:"Apakah mengetahui HANYA rasio keseluruhan yang dilaporkan (1:4) memberitahumu apakah rasio tepat itu berlaku di setiap departemen atau shift tunggal?",sample:"Ini bisa memberitahumu gambaran umum berapa banyak pasien yang biasanya menjadi tanggung jawab setiap perawat — tetapi tidak bisa memberitahumu apakah rasio ini konsisten berlaku di setiap shift, departemen, atau waktu (shift malam atau departemen gawat darurat mungkin memiliki rasio sebenarnya yang sangat berbeda), jadi rasio tunggal yang dilaporkan tidak menangkap variasi nyata penuh dalam kondisi staf yang sebenarnya."},
{n:97,type:"open",micro:"Investigasi nyata multi-langkah",q:"Rancang rencana untuk mengetahui, menggunakan rasio, kira-kira bagaimana pengeluaran mingguanmu terdistribusi di beberapa kategori (seperti makanan, hiburan, dan tabungan), tanpa melacak setiap transaksi dengan presisi ekstrem.",explain:"Menerapkan strategi 'perkirakan total kategori yang wajar, lalu nyatakan sebagai rasio yang disederhanakan' pada penyelidikan diri berbasis rasio dunia nyata yang benar-benar praktis.",hint:"Akankah memperkirakan pengeluaranmu dalam jumlah bulat wajar per kategori (alih-alih transaksi tepat) tetap memberikan gambaran rasio yang berguna dan praktis dari minggumu?",sample:"Perkirakan kira-kira total pengeluaranmu di setiap kategori utama selama seminggu khas (dibulatkan ke jumlah wajar terdekat alih-alih melacak setiap transaksi), nyatakan jumlah perkiraan ini sebagai rasio yang disederhanakan (seperti makanan:hiburan:tabungan), dan gunakan rasio itu untuk mendapat gambaran praktis dan berguna tentang prioritas pengeluaranmu tanpa perlu pelacakan transaksi-per-transaksi yang mustahil presisi."},
{n:98,type:"open",micro:"Rasio dan teknologi",q:"Banyak aplikasi dan perangkat (seperti aplikasi peta GPS, aplikasi penskalaan resep, atau alat pengeditan foto) secara otomatis menangani perhitungan rasio dan proporsi di balik layar. Apa satu keuntungan dan satu risiko dari sepenuhnya mempercayai penskalaan otomatis semacam ini?",explain:"Memperluas penalaran rasio ke alat digital nyata, menimbang kenyamanan penskalaan proporsional otomatis melawan risiko kehilangan kemampuan memeriksa kewajaran hasil yang tak terduga.",hint:"Apakah sepenuhnya mengandalkan penskalaan otomatis sebuah aplikasi menghilangkan kemampuanmu sendiri untuk menyadari jika suatu hasil terlihat luar biasa besar atau kecil?",sample:"Keuntungan: alat-alat ini bisa secara instan dan akurat menskalakan rasio kompleks (seperti jarak peta atau jumlah resep) jauh lebih cepat daripada perhitungan manual, yang sangat nyaman. Risiko: mempercayai buta hasil penskalaan otomatis tanpa memahami rasio yang mendasarinya bisa membuat lebih sulit menangkap hasil yang tidak biasa atau tak terduga (seperti aplikasi resep menyarankan jumlah bahan yang aneh besarnya karena kesalahan input data), karena kamu tidak akan punya perasaan sendiri tentang apakah angka itu sebenarnya masuk akal."},
{n:99,type:"open",micro:"Menyelidiki angka rasio yang bertentangan",q:"Dua sumber berbeda memberikan rasio air-terhadap-semen yang sedikit berbeda yang direkomendasikan untuk jenis proyek beton yang sama (seperti 0,5:1 versus 0,6:1). Bagaimana seharusnya pembaca yang cermat menyikapi perbedaan seperti ini?",explain:"Menerapkan penalaran yang matang, skeptis namun adil, pada rekomendasi berbasis rasio yang tampak bertentangan, menghindari kepercayaan buta maupun tuduhan yang tidak adil.",hint:"Bisakah dua sumber benar-benar merekomendasikan rasio berbeda karena kondisi proyek atau standar yang berbeda, bukan karena salah satu membuat kesalahan?",sample:"Pembaca yang cermat sebaiknya menyadari bahwa rasio yang direkomendasikan seperti ini bisa benar-benar bervariasi berdasarkan faktor seperti kondisi spesifik proyek, bahan tepat yang digunakan, atau standar profesional atau wilayah yang berbeda, alih-alih mengasumsikan satu sumber sekadar membuat kesalahan, dan sebaiknya melihat bagaimana setiap sumber menggambarkan kondisi spesifik yang berlaku untuk rasio yang direkomendasikannya sebelum memutuskan mana yang dipercaya untuk proyek tertentu."},
{n:100,type:"open",micro:"Refleksi kapstone",q:"Melihat kembali skill Rasio & Proporsi ini — mulai dari benda dikelompokkan nyata seperti keranjang buah dan campuran cat, ke gambar diagram pita dan peta berskala, dan akhirnya ke penyederhanaan rasio abstrak, laju satuan, dan menyelesaikan proporsi — kebiasaan apa yang sekarang kamu miliki saat melihat atau mengerjakan sebuah rasio?",explain:"Menyebutkan kebiasaan baru yang konkret, terkait perjalanan konkret-ke-abstrak dari skill ini, adalah tanda paling jelas bahwa skill ini sudah tertanam.",hint:"Pikirkan momen dalam unit ini ketika sebuah rasio berhenti membutuhkan gambar atau konteks fisik dan mulai masuk akal sebagai hubungan abstrak dengan sendirinya.",sample:"Bersifat personal dan terbuka — carilah perubahan nyata, seperti secara otomatis memeriksa bahwa KEDUA sisi rasio diskalakan dengan faktor yang sama, membayangkan rasio sebagai diagram pita untuk menilai apakah itu masuk akal, atau lebih berhati-hati tentang jumlah mana yang datang lebih dulu saat menulis atau membaca rasio, alih-alih mengasumsikan urutan itu tidak penting."},
];
